CREATE TABLE TMP_PERSON(name VARCHAR(20), age DECIMAL(2), dep_id DECIMAL, pid DECIMAL, charge_amount_1 DECIMAL, ref21 DECIMAL, card2_no DECIMAL, string2number VARCHAR(20), PRIMARY KEY (pid))  WITH "ATOMICITY=TRANSACTIONAL,TEMPLATE=REPLICATED,CACHE_NAME=TBG_TMP_PERSON";
CREATE TABLE TMP_PERSON_LOG(name VARCHAR(20), age DECIMAL(2), dep_id DECIMAL, pid DECIMAL, PRIMARY KEY (pid)) WITH "ATOMICITY=TRANSACTIONAL,TEMPLATE=REPLICATED,CACHE_NAME=TBG_TMP_PERSON_LOG";
